function useModelEngine() {
    const {
        liteRTModelInstance,
        setLiteRTModelInstance,
        setLiteRTModelModel,
        setLiteRTModelStatus,
    } = useLiteRTModelStore();
    const models = useModelStore((s) => s.models);
    const hydrated = useModelStore((s) => s.hydrated);
    const initializingRef = useRef(false);
    const objectUrlRef = useRef<string | null>(null);

    useEffect(() => {
        if (!hydrated) return;
        if (liteRTModelInstance) return;
        if (initializingRef.current) return;

        const completedModel = MODELS.find(
            (m) => m.type === "language" && models[m.id]?.status === "completed"
        );
        if (!completedModel) {
            setLiteRTModelStatus("idle");
            return;
        }

        // WebGPU validation
        if (typeof navigator !== "undefined" && (!("gpu" in navigator) || !navigator.gpu)) {
            console.error("[use-model-engine] WebGPU is not supported or enabled in this browser.");
            setLiteRTModelStatus("error");
            return;
        }

        setLiteRTModelStatus("loading");
        initializingRef.current = true;
        console.log("[use-model-engine] Initializing LiteRT-LM engine for model:", completedModel);

        (async () => {
            try {
                const objectUrl = await getModelObjectURL(completedModel.id);
                if (!objectUrl) {
                    initializingRef.current = false;
                    setLiteRTModelStatus("idle");
                    return;
                }
                objectUrlRef.current = objectUrl;

                const engine = await Engine.create({
                    model: objectUrl,
                    mainExecutorSettings: {
                        maxNumTokens: 8192,
                    },
                });

                setLiteRTModelInstance(engine);
                setLiteRTModelModel(completedModel.id);
                setLiteRTModelStatus("ready");
            } catch (err) {
                console.error("[use-model-engine] Failed to initialize LiteRT-LM engine:", err);
                initializingRef.current = false;
                setLiteRTModelStatus("error");
            } finally {
                // Engine has ingested the model blob/stream — safe to revoke object URL
                if (objectUrlRef.current) {
                    URL.revokeObjectURL(objectUrlRef.current);
                    objectUrlRef.current = null;
                }
            }
        })();
    }, [hydrated, liteRTModelInstance, models, setLiteRTModelInstance, setLiteRTModelModel, setLiteRTModelStatus]);
}

function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return !!isMobile
}

function useNavigation(): NavigationState {
    const pathname = usePathname();
    const { currentChat } = useChatStore();

    const navigationState = useMemo(() => {
        // Determine current page and breadcrumb title based on pathname
        const currentPage = pathname;
        let breadcrumbTitle = "Ask Buddhi AI"; // Default for app layout

        // Map pathnames to breadcrumb titles
        const pathTitleMap: Record<string, string> = {
            "/chat": "Ask Buddhi AI",
            "/models": "Models",
        };

        // Handle dynamic routes and specific cases
        if (pathname.startsWith("/chat/")) {
            breadcrumbTitle = "Chat";

            const segments = pathname.split('/').filter(Boolean);
            if (currentChat?.title) {
                breadcrumbTitle = currentChat.title;
            } else if (segments.length > 1 && segments[1]) {
                breadcrumbTitle = `Chat - ${segments[1]}`;
            }
        } else {
            breadcrumbTitle = pathTitleMap[pathname] || "Ask Buddhi AI";
        }

        // Create navigation items with active state
        const navItems = SIDEBAR_DATA.navMain.map(item => ({
            ...item,
            isActive: item.url === currentPage
        }));

        return {
            currentPage,
            breadcrumbTitle,
            navItems
        };
    }, [pathname, currentChat]);

    return navigationState;
}

function blobToDataUrl(blob: Blob): Promise<string> {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result as string);
        reader.onerror = () =>
            reject(new Error("FileReader failed to convert Blob to data URL"));
        reader.readAsDataURL(blob);
    });
}

function isPlainTextCodeFence(line: string): boolean {
    const match = line.match(/^```(\w*)$/);
    if (!match) return false;
    const lang = match[1].toLowerCase();
    return (
        lang === "" ||
        lang === "text" ||
        lang === "plaintext" ||
        lang === "plain" ||
        lang === "markdown" ||
        lang === "md"
    );
}

async function resolveFileUrl(
    url: string | undefined,
    data: Uint8Array | string | undefined,
    mediaType: string,
): Promise<string | null> {
    if (url) {
        if (url.startsWith("data:")) return url;
        if (url.startsWith("blob:")) {
            try {
                const res = await fetch(url);
                const blob = await res.blob();
                return await blobToDataUrl(blob);
            } catch (err) {
                console.warn("[resolveFileUrl] Failed to fetch blob: URL:", err);
                return null;
            }
        }
        return url;
    }

    if (data instanceof Uint8Array) {
        const binary = Array.from(data, (b) => String.fromCharCode(b)).join("");
        return `data:${mediaType ?? "application/octet-stream"};base64,${btoa(binary)}`;
    }

    if (typeof data === "string") {
        return `data:${mediaType ?? "application/octet-stream"};base64,${data}`;
    }

    return null;
}

function stripOuterCodeFence(text: string): string {
    return text
        .replace(/^```[\w]*\n/, "") // strip opening fence + optional language tag
        .replace(/\n```\s*$/, "");  // strip closing fence + optional trailing whitespace
}

function stripTrailingTemplateTokens(text: string): string {
    return text
        .replace(/<turn\|>\s*$/, "")
        .replace(/<end_of_turn>\s*$/, "")
        .trimEnd();
}

async function uiMessagesToBuddhiMessages(
    messages: UIMessage[],
    supportsVision: boolean,
): Promise<BuddhiAIMessage[]> {
    return Promise.all(
        messages.map(async (msg) => {
            const contentParts: BuddhiAIChatTemplate[] = [];
            let hasMedia = false;

            for (const part of msg.parts) {
                if (part.type === "text") {
                    contentParts.push({ type: "text", text: part.text });
                } else if (part.type === "file") {
                    const filePart = part as FileUIPart;
                    const mediaType = filePart.mediaType ?? "";
                    const rawData = (filePart as unknown as { data?: Uint8Array | string }).data;

                    if (mediaType.startsWith("image/")) {
                        if (!supportsVision) {
                            console.warn(
                                `[uiMessagesToBuddhiMessages] Model does not support vision. ` +
                                `Skipping image "${filePart.filename ?? "image"}".`
                            );
                        } else {
                            const dataUrl = await resolveFileUrl(filePart.url, rawData, mediaType);
                            if (dataUrl) {
                                contentParts.push({
                                    type: "image",
                                    url: dataUrl,
                                    mediaType,
                                    fileName: filePart.filename,
                                });
                                hasMedia = true;
                            }
                        }
                    } else if (mediaType.startsWith("audio/")) {
                        if (!supportsVision) {
                            console.warn(
                                `[uiMessagesToBuddhiMessages] Model does not support audio. ` +
                                `Skipping audio "${filePart.filename ?? "audio"}".`
                            );
                        } else {
                            const dataUrl = await resolveFileUrl(filePart.url, rawData, mediaType);
                            if (dataUrl) {
                                contentParts.push({
                                    type: "audio",
                                    url: dataUrl,
                                    mediaType,
                                    fileName: filePart.filename,
                                });
                                hasMedia = true;
                            }
                        }
                    }
                }
            }

            const content: BuddhiAIMessage["content"] = hasMedia
                ? contentParts
                : contentParts
                    .filter((p) => p.type === "text")
                    .map((p) => p.text!)
                    .join("\n");

            return {
                role: msg.role as BuddhiAIMessage["role"],
                content,
            };
        }),
    );
}

function extractTextFromContent(
    content: BuddhiAIChatTemplate[] | string
): string {
    if (typeof content === "string") return content;
    return content
        .filter((item) => item.type === "text" && item.text != null)
        .map((item) => item.text!)
        .join("\n");
}

function generateGemma3nTemplate(messages: BuddhiAIMessage[]): Prompt {
    // Extract system prefix from the first message (if present).
    const systemPrefix =
        messages[0].role === "system"
            ? extractTextFromContent(messages[0].content)
            : null;

    const parts: Prompt = [];

    for (const message of messages) {
        const role = message.role === "assistant" ? "model" : message.role;

        // The system message is merged into the first turn and handled below.
        if (message.role === "system") {
            parts.push(`<start_of_turn>${role}\n${systemPrefix!.trim()}\n<end_of_turn>\n`);
            continue;
        }

        if (message.role === "user" && typeof message.content === "string") {
            // First user turn: prepend the system prefix when no explicit system
            // message was provided (chat-api.ts injects it directly into content).
            parts.push(
                `<start_of_turn>${role}\n${message.content.trim()}\n<end_of_turn>\n`
            );
            continue;
        }

        if (message.role === "user" && Array.isArray(message.content)) {
            for (const item of message.content) {
                if (item.type === "text" && item.text) {
                    parts.push(
                        `<start_of_turn>${role}\n${item.text.trim()}\n`
                    );
                } else if (item.type === "image" && item.url) {
                    parts.push({ imageSource: item.url } as PromptPart);
                } else if (item.type === "audio" && item.url) {
                    parts.push({ audioSource: item.url } as PromptPart);
                }
            }
            parts.push("<end_of_turn>\n");
            continue;
        }

        if (message.role === "assistant" && typeof message.content === "string") {
            parts.push(
                `<start_of_turn>${role}\n${message.content.trim()}\n<end_of_turn>\n`
            );
            continue;
        }

        // Assistant message with array content — extract text only.
        if (message.role === "assistant" && Array.isArray(message.content)) {
            const text = extractTextFromContent(message.content).trim();
            if (text) {
                parts.push(
                    `<start_of_turn>${role}\n${text}\n<end_of_turn>\n`
                );
            }
            continue;
        }
    }

    // Open the model's response turn.
    parts.push("<start_of_turn>model\n");
    return parts;
}

function serializeValue(value: unknown): string {
    if (value === null || value === undefined) return "null";
    if (typeof value === "string") return `<|"|>${value}<|"|>`;
    if (typeof value === "number" || typeof value === "boolean")
        return String(value);
    if (Array.isArray(value))
        return `[${value.map(serializeValue).join(",")}]`;
    if (typeof value === "object") {
        const entries = Object.entries(value as Record<string, unknown>)
            .map(([k, v]) => `${k}:${serializeValue(v)}`)
            .join(",");
        return `{${entries}}`;
    }
    // Fallback — wrap unknown types as strings
    return `<|"|>${String(value)}<|"|>`;
}

function serializeObject(obj: Record<string, unknown>): string {
    const entries = Object.entries(obj)
        .map(([k, v]) => `${k}:${serializeValue(v)}`)
        .join(",");
    return `{${entries}}`;
}

function serializeToolCall(tc: BuddhiAIToolCall): string {
    if (Object.keys(tc.arguments).length === 0) {
        return `<|tool_call>call:${tc.name}{}<tool_call|>`;
    }
    return `<|tool_call>call:${tc.name}${serializeObject(tc.arguments)}<tool_call|>`;
}

function serializeToolDeclaration(tool: BuddhiAIToolDefinition): string {
    const schema: Record<string, unknown> = {
        description: tool.description,
    };
    if (tool.parameters && Object.keys(tool.parameters).length > 0) {
        schema.parameters = tool.parameters;
    }
