function extractWebCodeFromMarkdown(markdown: string): ExtractedCodeBlock | null {
    if (!markdown) return null;

    // 1. Look for completed HTML block
    const htmlRegex = /```(?:html|htm)\s*([\s\S]*?)```/i;
    const match = markdown.match(htmlRegex);
    if (match && match[1]?.trim()) {
        return {
            language: "html",
            code: match[1].trim(),
            isComplete: true,
        };
    }

    // 2. Look for open/streaming HTML block (unclosed triple backticks)
    const openHtmlRegex = /```(?:html|htm)\s*([\s\S]*)$/i;
    const openMatch = markdown.match(openHtmlRegex);
    if (openMatch && openMatch[1]?.trim()) {
        return {
            language: "html",
            code: openMatch[1].trim(),
            isComplete: false,
        };
    }

    // 3. Fallback: check if raw text contains DOCTYPE or <html>
    if (markdown.includes("<!DOCTYPE html>") || markdown.includes("<html") || markdown.includes("<body")) {
        return {
            language: "html",
            code: markdown.trim(),
            isComplete: true,
        };
    }

    return null;
}

function setupLiteRTLogFilter(): void {
    if (typeof window === "undefined") return;

    const globalObj = window as unknown as { __litert_log_filter_installed__?: boolean };
    if (globalObj.__litert_log_filter_installed__) return;
    globalObj.__litert_log_filter_installed__ = true;

    const originalError = console.error.bind(console);

    const isLiteRTDiagnostic = (firstArg: unknown): boolean => {
        if (typeof firstArg !== "string") return false;

        return (
            firstArg.startsWith("INFO: [") ||
            firstArg.startsWith("WARNING: [") ||
            /^(?:INFO|WARNING):\s*\[[\w_.-]+\.cc:\d+\]/.test(firstArg) ||
            /^W\d{4}\s+[\d:.]+\s+\d+\s+[\w_.-]+\.cc:\d+\]/.test(firstArg) ||
            firstArg.includes("npu_registry.cc") ||
            firstArg.includes("environment.cc") ||
            firstArg.includes("accelerator_registry.cc") ||
            firstArg.includes("gpu_registry.cc") ||
            firstArg.includes("cpu_registry.cc") ||
            firstArg.includes("mel_filterbank.cc") ||
            firstArg.includes("kLiteRtStatusErrorInvalidArgument")
        );
    };

    console.error = (...args: unknown[]) => {
        if (args.length > 0 && isLiteRTDiagnostic(args[0])) {
            console.warn("[LiteRT]", ...args);
            return;
        }
        originalError(...args);
    };
}

